// ------------------------------------------------------------------
// UI
// ------------------------------------------------------------------
const C = {
  bg: "#0b0f19", panel: "#121826", panel2: "#0f1420", border: "#232c40",
  text: "#e8edf7", sub: "#9aa7bd", accent: "#6ea8fe", accent2: "#7ef0c0",
  warn: "#ffcf6e", danger: "#ff7a90", spotlight: "#c9a6ff",
};

const catColor = (cat) => ({
  "AI Security": "#ff7a90",
  "Foundation Models": "#6ea8fe",
  "AI Regulation": "#ffcf6e",
  "Generative AI": "#7ef0c0",
  "Funding": "#7ef0c0",
  "AI Infrastructure": "#ffcf6e",
  "AI Chips / Semiconductor": "#8fd4ff",
  "M&A": "#f0a6d8",
  "Enterprise AI": "#7ef0c0",
  "Robotics": "#ffb27a",
  "AI x Healthcare": "#8ef0d6",
  "Agentic AI": "#b7a6ff",
  "Open Source AI": "#a6d8ff",
}[cat] || "#9aa7bd");

function ScoreBadge({ score }) {
  const color = score >= 75 ? C.danger : score >= 65 ? C.warn : C.accent;
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: 6, fontWeight: 700, color }}>
      <span style={{ fontSize: 22 }}>{score}</span>
      <span style={{ fontSize: 11, color: C.sub }}>/100</span>
    </div>
  );
}

function Bar({ label, value }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8, margin: "3px 0" }}>
      <span style={{ width: 78, fontSize: 11, color: C.sub }}>{label}</span>
      <div style={{ flex: 1, height: 6, background: C.panel2, borderRadius: 4, overflow: "hidden" }}>
        <div style={{ width: `${value}%`, height: "100%", background: C.accent }} />
      </div>
      <span style={{ width: 24, textAlign: "right", fontSize: 11, color: C.text }}>{value}</span>
    </div>
  );
}

function ItemCard({ item, lang, open, onToggle }) {
  const cc = catColor(item.category);
  return (
    <div style={{ background: C.panel, border: `1px solid ${item.spotlight ? C.spotlight : C.border}`, borderRadius: 14, padding: 16, marginBottom: 14 }}>
      <div style={{ display: "flex", justifyContent: "space-between", gap: 12, alignItems: "flex-start" }}>
        <div style={{ flex: 1 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 6 }}>
            <span style={{ fontSize: 12, fontWeight: 700, color: C.bg, background: cc, borderRadius: 20, padding: "2px 9px" }}>#{item.rank}</span>
            <span style={{ fontSize: 11, color: cc, border: `1px solid ${cc}`, borderRadius: 20, padding: "2px 8px" }}>{item.category}</span>
            {item.spotlight && <span style={{ fontSize: 11, color: C.spotlight, border: `1px solid ${C.spotlight}`, borderRadius: 20, padding: "2px 8px" }}>🔬 Breakthrough Spotlight</span>}
            <span style={{ fontSize: 11, color: C.sub }}>{item.company}</span>
          </div>
          <div style={{ fontSize: 15, fontWeight: 600, lineHeight: 1.5 }}>{item.headline[lang]}</div>
        </div>
        <ScoreBadge score={item.score} />
      </div>

      <p style={{ margin: "12px 0 8px", fontSize: 13.5, color: C.text, lineHeight: 1.7 }}>{item.summary[lang]}</p>

      <button onClick={() => onToggle(item.rank)} style={{ background: "transparent", color: C.accent, border: `1px solid ${C.border}`, borderRadius: 8, padding: "5px 12px", cursor: "pointer", fontSize: 12 }}>
        {open ? (lang === "ja" ? "▲ 分析を閉じる" : "▲ Hide analysis") : (lang === "ja" ? "▼ 6レンズ分析を見る" : "▼ Show 6-lens analysis")}
      </button>

      {open && (
        <div style={{ marginTop: 12, display: "grid", gap: 10 }}>
          <div style={{ background: C.panel2, borderRadius: 10, padding: 12 }}>
            <div style={{ fontSize: 11, color: C.sub, marginBottom: 6 }}>{lang === "ja" ? "スコア内訳（6軸）" : "Score breakdown (6 axes)"}</div>
            <Bar label="Market" value={item.sub.market} />
            <Bar label="Technology" value={item.sub.tech} />
            <Bar label="Business" value={item.sub.business} />
            <Bar label="Competitive" value={item.sub.competitive} />
            <Bar label="Investment" value={item.sub.investment} />
            <Bar label="Novelty" value={item.sub.novelty} />
          </div>
          {item.terms && (
            <Field label={lang === "ja" ? "用語メモ" : "Terms"} text={item.terms[lang]} color={C.sub} />
          )}
          <Field label={lang === "ja" ? "なぜ重要か" : "Why it matters"} text={item.why[lang]} />
          <Field label={lang === "ja" ? "ビジネス / ユニットエコノミクス" : "Business / unit economics"} text={item.business[lang]} />
          <Field label={lang === "ja" ? "競争地図" : "Competitive"} text={item.competitive[lang]} />
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
            <Field label={lang === "ja" ? "誰が得をするか" : "Who benefits"} text={item.benefits[lang]} color={C.accent2} />
            <Field label={lang === "ja" ? "誰が脅かされるか" : "Who is threatened"} text={item.threatened[lang]} color={C.danger} />
          </div>
          <Field label={lang === "ja" ? "次に起きること" : "What happens next"} text={item.next[lang]} />
          <a href={item.source} target="_blank" rel="noreferrer" style={{ fontSize: 12, color: C.accent }}>
            🔗 {item.sourceName}
          </a>
        </div>
      )}
    </div>
  );
}

function Field({ label, text, color }) {
  return (
    <div style={{ background: C.panel2, borderRadius: 10, padding: 12 }}>
      <div style={{ fontSize: 11, color: color || C.accent, marginBottom: 4, fontWeight: 600 }}>{label}</div>
      <div style={{ fontSize: 13, color: C.text, lineHeight: 1.7 }}>{text}</div>
    </div>
  );
}

export default function App() {
  const [lang, setLang] = useState("ja");
  const [view, setView] = useState("daily");
  const [openRank, setOpenRank] = useState(1); // Spotlight (Anthropic MHS, rank 1) open by default
  const t = (ja, en) => (lang === "ja" ? ja : en);

  const tabBtn = (id, label) => (
    <button onClick={() => setView(id)} style={{
      background: view === id ? C.accent : "transparent", color: view === id ? C.bg : C.text,
      border: `1px solid ${view === id ? C.accent : C.border}`, borderRadius: 999, padding: "7px 16px",
      cursor: "pointer", fontSize: 13, fontWeight: 600,
    }}>{label}</button>
  );

  const avg = useMemo(() => Math.round(DIGEST.items.reduce((s, i) => s + i.score, 0) / DIGEST.items.length), []);

  return (
    <div style={{ minHeight: "100vh", background: C.bg, color: C.text, fontFamily: "system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif" }}>
      <div style={{ maxWidth: 920, margin: "0 auto", padding: "24px 18px 60px" }}>
        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, flexWrap: "wrap", marginBottom: 8 }}>
          <div>
            <div style={{ fontSize: 12, color: C.sub, letterSpacing: 1 }}>AI INTELLIGENCE DIGEST</div>
            <h1 style={{ margin: "2px 0 0", fontSize: 26 }}>{t("AI インテリジェンス・ダッシュボード", "AI Intelligence Dashboard")}</h1>
            <div style={{ fontSize: 13, color: C.sub, marginTop: 2 }}>{DIGEST.date} · {t("平均重要度", "Avg importance")} {avg}/100</div>
          </div>
          <button onClick={() => setLang(lang === "ja" ? "en" : "ja")} style={{ background: C.panel, color: C.text, border: `1px solid ${C.border}`, borderRadius: 999, padding: "8px 16px", cursor: "pointer", fontSize: 13, fontWeight: 600 }}>
            {lang === "ja" ? "EN" : "日本語"}
          </button>
        </div>

        {/* Signal */}
        <div style={{ background: "linear-gradient(135deg, #14203a, #101725)", border: `1px solid ${C.border}`, borderRadius: 14, padding: 16, margin: "14px 0 18px" }}>
          <div style={{ fontSize: 12, color: C.accent2, fontWeight: 700, marginBottom: 6 }}>🎯 {t("今日の AI シグナル", "Today's AI Signal")}</div>
          <div style={{ fontSize: 14, lineHeight: 1.75 }}>{DIGEST.signal[lang]}</div>
        </div>

        {/* Tabs */}
        <div style={{ display: "flex", gap: 8, marginBottom: 18, flexWrap: "wrap" }}>
          {tabBtn("daily", t("日次 Top 5", "Daily Top 5"))}
          {tabBtn("weekly", t("週次", "Weekly"))}
          {tabBtn("startups", t("スタートアップ", "Startups"))}
        </div>

        {/* Daily */}
        {view === "daily" && (
          <>
            {DIGEST.items.map((item) => (
              <ItemCard key={item.rank} item={item} lang={lang} open={openRank === item.rank} onToggle={(r) => setOpenRank(openRank === r ? -1 : r)} />
            ))}
            <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16, marginTop: 6 }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: C.warn, marginBottom: 8 }}>📡 {t("レーダー（次点 / 監視中）", "On the radar (next-tier / watching)")}</div>
              <ul style={{ margin: 0, paddingLeft: 18, display: "grid", gap: 6 }}>
                {DIGEST.radar.map((r, i) => <li key={i} style={{ fontSize: 13, color: C.sub, lineHeight: 1.6 }}>{r[lang]}</li>)}
              </ul>
            </div>
          </>
        )}

        {/* Weekly */}
        {view === "weekly" && (
          <div style={{ display: "grid", gap: 14 }}>
            <div style={{ fontSize: 13, color: C.sub }}>{t("対象週", "Week")}: {WEEKLY.range}</div>
            <WeeklyBlock title={t("主要トレンド", "Major Trends")} items={WEEKLY.trends} lang={lang} />
            <WeeklyBlock title={t("台頭する企業", "Emerging Companies")} items={WEEKLY.emerging} lang={lang} />
            <WeeklyBlock title={t("技術トレンド", "Technology Trends")} items={WEEKLY.techTrends} lang={lang} />
            <WeeklyBlock title={t("投資シグナル", "Investment Signals")} items={WEEKLY.investmentSignals} lang={lang} />
            <WeeklyBlock title={t("来週の注目", "What to Watch Next Week")} items={WEEKLY.watchNext} lang={lang} />
          </div>
        )}

        {/* Startups */}
        {view === "startups" && (
          <div style={{ display: "grid", gap: 12 }}>
            {STARTUPS.map((s) => (
              <div key={s.domain} style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                  <div>
                    <div style={{ fontSize: 16, fontWeight: 700 }}>{s.company}</div>
                    <a href={s.website} target="_blank" rel="noreferrer" style={{ fontSize: 12, color: C.accent }}>{s.domain}</a>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <ScoreBadge score={s.score} />
                    <div style={{ fontSize: 12, color: C.warn }}>{s.verdict}</div>
                  </div>
                </div>
                <div style={{ fontSize: 13, color: C.sub, marginTop: 8, lineHeight: 1.6 }}>{s.note[lang]}</div>
                <div style={{ fontSize: 11, color: C.sub, marginTop: 8, display: "flex", gap: 14, flexWrap: "wrap" }}>
                  <span>{t("初出", "First")}: {s.first}</span>
                  <span>{t("最終", "Last")}: {s.last}</span>
                  <span>{t("Watchlist", "Watchlist")}: {s.watchlist ? "Yes" : "No"}</span>
                </div>
              </div>
            ))}
            <div style={{ fontSize: 11, color: C.sub, lineHeight: 1.6 }}>
              {t("※ Registry は投資フル分析済み企業のみ。本日ニュースで扱った Anthropic/Google/Nvidia/Hugging Face/Sony/Warner 等はフル分析（§5.3）未実施のため未登録。フル分析時は各社 Domain 照合から開始（§5.4）。",
                 "Note: the registry lists only fully investment-analyzed companies. Today's news names — Anthropic, Google, Nvidia, Hugging Face, Sony, Warner — are not registered (full §5.3 analysis pending). A full analysis starts from each company's domain check (§5.4).")}
            </div>
          </div>
        )}

        <div style={{ marginTop: 28, paddingTop: 14, borderTop: `1px solid ${C.border}`, fontSize: 11, color: C.sub, lineHeight: 1.6 }}>
          {t("単一正本：この画面の内容の正は DIGEST オブジェクト。出典は各カードのリンク先を参照。項目1(Anthropic MHS)は Anthropic 研究プレビュー8/27（AI が実機を操る共通規格・MCP の物理版・統合を数週間→数時間・初期パートナー Genentech/UW Baker/CMU/Janelia/QuEra/Tetsuwan、max(Tech,Novelty)=86 → Spotlight）。項目2(Sony/Warner 対 Anthropic)は TechCrunch/MBW 8/29（音楽出版社が海賊版学習で提訴・前例は7月$1.5B の Bartz 判決）。項目3(Google Gemini Omni 1.1 Flash)は Google DeepMind/MarkTechPost 8/29（40秒・始点/終点フレーム・4K アップスケール・$0.03/秒）。項目4(EU×Nvidia/HF)は TechTimes 8/28（$12.9B 買収に反トラスト警戒・8/27④の続報）。項目5(AI 版 FINRA)は The Information 8/27–28（業界主導 SRO 草案・関連 EO は停滞）。選定＝直近3日窓（8/28–30）＋加重重要度＋Spotlight。平均重要度59。",
             "Single source of truth: the DIGEST object. See each card's link for sources. Item 1 (Anthropic MHS) is Anthropic's research preview, Aug 27 (a shared standard for AI to operate real machines; MCP's physical version; integration weeks → hours; early partners Genentech/UW Baker/CMU/Janelia/QuEra/Tetsuwan; max(Tech,Novelty)=86 → Spotlight). Item 2 (Sony/Warner v Anthropic) is TechCrunch/MBW, Aug 29 (music publishers sue over pirated training; precedent is July's $1.5B Bartz ruling). Item 3 (Google Gemini Omni 1.1 Flash) is Google DeepMind/MarkTechPost, Aug 29 (40 sec, first/last frame, 4K upscaling, $0.03/sec). Item 4 (EU × Nvidia/HF) is TechTimes, Aug 28 (antitrust wariness of the $12.9B acquisition; a follow-up to Aug 27's item 4). Item 5 (AI FINRA) is The Information, Aug 27–28 (an industry-led SRO draft; a related EO stalled). Selection = 3-day window (Aug 28–30) + weighted importance + Spotlight. Avg importance 59.")}
        </div>
      </div>
    </div>
  );
}

function WeeklyBlock({ title, items, lang }) {
  return (
    <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
      <div style={{ fontSize: 13, fontWeight: 700, color: C.accent, marginBottom: 8 }}>{title}</div>
      <ul style={{ margin: 0, paddingLeft: 18, display: "grid", gap: 7 }}>
        {items.map((it, i) => <li key={i} style={{ fontSize: 13, color: C.text, lineHeight: 1.7 }}>{it[lang]}</li>)}
      </ul>
    </div>
  );
}
